-- Seed: отзывы
INSERT OR REPLACE INTO testimonials (id, author_name, author_city, child_age, content, rating, is_published, sort_order) VALUES
(1, 'Анна К.', 'Москва', '4 года', 'Мы занимаемся уже два месяца, и дочка уже знает все цвета и животных по-испански. Занятия очень комфортные — всё продумано, не нужно ничего самой придумывать!', 5, 1, 1),
(2, 'Светлана М.', 'Санкт-Петербург', '5 лет', 'Я сама не знала ни слова по-испански, но с этими материалами всё оказалось очень просто. Ребёнок обожает песенки! Рекомендую всем мамам.', 5, 1, 2),
(3, 'Елена Р.', 'Краснодар', '3 года', 'Искала что-то, чем можно заниматься дома без репетитора. Нашла идеально! Карточки, игры, конспекты — всё есть. Марина отвечает быстро, если есть вопросы.', 5, 1, 3),
(4, 'Ольга Д.', 'Екатеринбург', '6 лет', 'Сын был совершенно не заинтересован в языках, а теперь сам просит заниматься испанским. Очень доступный и игровой формат.', 5, 1, 4),
(5, 'Наталья В.', 'Новосибирск', '4 года', 'Отличный курс! Готовые уроки экономят кучу времени. Занимаемся 15-20 минут в день и прогресс заметен уже через неделю.', 5, 1, 5);

-- Seed: FAQ
INSERT OR REPLACE INTO faq_items (id, question, answer, is_published, sort_order) VALUES
(1, 'А если я сама не говорю по-испански?', 'Это не проблема! Курс создан специально для мам с нулевым уровнем. В каждом уроке есть полная озвучка, транскрипция и подробные инструкции. Вы будете учиться вместе с ребёнком.', 1, 1),
(2, 'Сколько длится курс?', 'Курс рассчитан на 27 тематических блоков. Темп вы выбираете сами — можно заниматься каждый день по 15–20 минут или несколько раз в неделю. Материалы остаются у вас навсегда.', 1, 2),
(3, 'Нужно ли всё распечатывать?', 'Нет, это необязательно. Многие материалы удобно использовать с экрана. Но если хотите — карточки и рабочие листы отлично распечатываются в формате А4.', 1, 3),
(4, 'Подойдёт ли ребёнку, если он уже учит английский?', 'Да, отлично подойдёт! Дети легко осваивают несколько языков одновременно, особенно в игровом формате. Знание английского только поможет — ребёнок уже привык к самому процессу изучения языков.', 1, 4),
(5, 'Есть ли обратная связь?', 'Да! После получения курса вы можете задавать вопросы автору. Марина отвечает в мессенджерах и помогает разобраться, если что-то непонятно.', 1, 5),
(6, 'С какого возраста можно начинать?', 'Оптимально — с 2,5–3 лет. Именно в этом возрасте дети легче всего воспринимают иностранные языки через игру и песни. Но курс подойдёт и для детей постарше — до 7–8 лет.', 1, 6);

